css:
.scalesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf7;
    background: radial-gradient(1200px 600px at 80% -10%, #1b2550 0%, #0c1230 55%, #070b22 100%);
    border-radius: 18px;
}

.scalesim-container * {
    box-sizing: border-box;
}

.scalesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #141d45 0%, #1c2a66 50%, #0d6a8f 120%);
    color: #f3f7ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(96, 165, 250, 0.25);
    box-shadow: 0 12px 34px rgba(8, 13, 40, 0.55);
}

.scalesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    background: linear-gradient(90deg, #7dd3fc 0%, #a5b4fc 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.scalesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #9fd5f5;
    background: rgba(125, 211, 252, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(125, 211, 252, 0.2);
}

.scalesim-subtitle {
    margin: 14px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd8f0;
}

.scalesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b9c6ec;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.scalesim-period-counter #currentDay,
.scalesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #7dd3fc;
}

.scalesim-round-name {
    background: rgba(125, 211, 252, 0.14);
    color: #9fe0fb;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(125, 211, 252, 0.25);
}

.scalesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #fcd34d;
    background: rgba(252, 211, 77, 0.12);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(252, 211, 77, 0.25);
}

.scalesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.scalesim-status-card {
    background: rgba(20, 28, 64, 0.72);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.45);
    border-top: 4px solid #6366f1;
    backdrop-filter: blur(6px);
}

.scalesim-card-arr { border-top-color: #34d399; }
.scalesim-card-product { border-top-color: #38bdf8; }
.scalesim-card-customer { border-top-color: #a78bfa; }
.scalesim-card-runway { border-top-color: #fbbf24; }

.scalesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea0cc;
}

.scalesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf0ff;
}

.scalesim-card-arr .scalesim-value { color: #34d399; }
.scalesim-card-product .scalesim-value { color: #38bdf8; }
.scalesim-card-customer .scalesim-value { color: #a78bfa; }
.scalesim-card-runway .scalesim-value { color: #fbbf24; }

.scalesim-sublabel {
    font-size: 0.76rem;
    color: #8595c0;
    line-height: 1.35;
}

.scalesim-runway-danger { border-top-color: #ef4444; }
.scalesim-runway-danger .scalesim-value { color: #f87171; }

.scalesim-customer-low { border-top-color: #ef4444; }
.scalesim-customer-low .scalesim-value { color: #f87171; }

.scalesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #101737 0%, #16214d 100%);
    color: #dce6ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid rgba(99, 130, 220, 0.22);
}

.scalesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #7dd3fc;
}

.scalesim-budget-over #budgetDisplay {
    color: #f87171;
}

.scalesim-briefing {
    display: flex;
    gap: 14px;
    background: rgba(20, 28, 64, 0.7);
    border-left: 5px solid #38bdf8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.scalesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #bfe4fb;
    margin-bottom: 6px;
}

.scalesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd8f0;
}

.scalesim-briefing-text strong { color: #34d399; }
.scalesim-briefing-text em { color: #fcd34d; font-style: italic; }

.scalesim-controls {
    background: rgba(16, 23, 55, 0.78);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf0ff;
    border-bottom: 2px solid rgba(99, 130, 220, 0.25);
    padding-bottom: 8px;
}

.scalesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c2cdec;
    margin: 14px 0 6px;
}

.scalesim-container select,
.scalesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(99, 130, 220, 0.4);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1538;
    color: #e8edf7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.scalesim-container select:focus,
.scalesim-container input[type="number"]:focus {
    outline: none;
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
}

.scalesim-container select option {
    background-color: #0e1538;
    color: #e8edf7;
}

.scalesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38bdf8;
}

.scalesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb3e4;
    margin-top: 4px;
}

.scalesim-range-readout span:last-child {
    color: #34d399;
    font-weight: 800;
}

.scalesim-hint {
    font-size: 0.8rem;
    color: #8595c0;
    margin-top: 4px;
    line-height: 1.4;
}

.scalesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.scalesim-container .btn-primary {
    background: linear-gradient(135deg, #2563eb 0%, #38bdf8 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #06122b;
    box-shadow: 0 8px 20px rgba(37, 99, 235, 0.35);
}

.scalesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.scalesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: rgba(99, 130, 220, 0.4);
    color: #9fb3e4;
    background: transparent;
}

.scalesim-coach {
    background: linear-gradient(135deg, #0d6a8f 0%, #1c2a66 100%);
    color: #eaf6ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(125, 211, 252, 0.25);
    box-shadow: 0 8px 22px rgba(6, 10, 34, 0.45);
}

.scalesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9fe0fb;
    margin-bottom: 8px;
}

.scalesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.scalesim-coach-body strong { color: #fde68a; }
.scalesim-coach-body em { color: #fca5a5; font-style: italic; }

.scalesim-history,
.scalesim-chart {
    background: rgba(16, 23, 55, 0.78);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-history h3,
.scalesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf0ff;
}

.scalesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd8f0;
}

.scalesim-container table#usfHistoryTable th {
    background: rgba(56, 189, 248, 0.1);
    color: #bfe4fb;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(99, 130, 220, 0.3);
}

.scalesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(99, 130, 220, 0.14);
}

.scalesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(56, 189, 248, 0.04);
}

.scalesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .scalesim-container {
        padding: 14px;
    }
    .scalesim-header h1 {
        font-size: 1.7rem;
    }
    .scalesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .scalesim-value {
        font-size: 2rem;
    }
    .scalesim-clock {
        margin-left: 0;
    }
    .scalesim-period-counter {
        font-size: 0.88rem;
    }
    .scalesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .scalesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

